export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

export type Customer = {
  yearsWithMHPCO: number;
};

export function quote(
  items: Item[],
  customer: Customer = { yearsWithMHPCO: 0 },
  previousContracts = 0,
): number {
  let base = 0;
  let surcharges = 0;
  for (const item of items) {
    const itemBase = BASE_PREMIUMS[item.type];
    base += itemBase;
    if (item.cursed) {
      surcharges += itemBase * 0.5;
    }
    if ((item.enchantment ?? 0) >= 5) {
      surcharges += itemBase * 0.3;
    }
  }
  let policyModifiers = base * 0.1;
  if (customer.yearsWithMHPCO >= 2) {
    policyModifiers -= base * 0.2;
  }
  if (previousContracts >= 1) {
    policyModifiers -= base * 0.15;
  }
  return base + surcharges + policyModifiers + 5;
}

