  yearsWithMHPCO: number;
};

function blockDiscount(items: Item[]): number {
  let discount = 0;
  for (const type of COMPONENT_TYPES) {
    const count = items.filter((item) => item.type === type).length;
    if (count === COMPONENT_BLOCK_SIZE) {
      discount += count * BASE_PREMIUMS[type] - COMPONENT_BLOCK_PREMIUM;
    }
  }
  return discount;
}

export function quote(
  items: Item[],
  customer: Customer = { yearsWithMHPCO: 0 },
  previousContracts = 0,
): number {
  let base = 0;
  let surcharges = 0;
  for (const item of items) {
    const itemBase = BASE_PREMIUMS[item.type];
    base += itemBase;
    if (item.cursed) {
      surcharges += itemBase * 0.5;
    }
    if ((item.enchantment ?? 0) >= 5) {
      surcharges += itemBase * 0.3;
    }
  }
  let policyModifiers = base * 0.1;
  if (customer.yearsWithMHPCO >= 2) {
    policyModifiers -= base * 0.2;
  }
  if (previousContracts >= 1) {
    policyModifiers -= base * 0.15;
  }
  return Math.ceil(base + surcharges + policyModifiers + 5);
}

