import type { Policy } from './policy';

export type Damage = {
  itemType: string;
  amount: number;
};

export type Incident = {
  cause: string;
  damages: Damage[];
};

export type ClaimResult = {
  payout: number;
  remainingCap: number;
};

const DEDUCTIBLE = 100;

export function claim(policy: Policy, incident: Incident): ClaimResult {
  let payout = 0;
  for (const damage of incident.damages) {
    const item = policy.items.find((candidate) => candidate.type === damage.itemType);
    const reimbursed = (item?.enchantment ?? 0) >= 8 ? damage.amount * 0.5 : damage.amount;
    payout += reimbursed - DEDUCTIBLE;
  }
  payout = Math.min(payout, policy.remainingCap);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}

