import type { Item } from './quote';

const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

export function insuranceValue(type: string): number {
  const value = INSURANCE_VALUES[type];
  if (value === undefined) {
    throw new Error(`unknown item type: ${type}`);
  }
  return value;
}

export function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + insuranceValue(item.type), 0);
}

export type Policy = {
  items: Item[];
  remainingCap: number;
};

export function createPolicy(items: Item[]): Policy {
  return { items, remainingCap: 2 * insuranceSum(items) };
}

