import type { Policy } from './policy';

export type Damage = {
  itemType: string;
  amount: number;
};

export type Incident = {
  cause: string;
  damages: Damage[];
};

export type ClaimResult = {
  payout: number;
  remainingCap: number;
};

const DEDUCTIBLE = 100;

export function claim(policy: Policy, incident: Incident): ClaimResult {
  let payout = 0;
  const available = [...policy.items];
  for (const damage of incident.damages) {
    if (damage.amount < 0) {
      throw new Error(`negative damage amount: ${damage.amount}`);
    }
    const index = available.findIndex((candidate) => candidate.type === damage.itemType);
    if (index === -1) {
      throw new Error(`item not covered by the policy: ${damage.itemType}`);
    }
    const [item] = available.splice(index, 1);
    const reimbursed = (item.enchantment ?? 0) >= 8 ? damage.amount * 0.5 : damage.amount;
    payout += reimbursed - DEDUCTIBLE;
  }
  payout = Math.min(Math.floor(payout), policy.remainingCap);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}

